package com.hbm.client.generator.stirling;
import com.hbm.client.gui.font.LegacyFonts;import com.hbm.machine.generator.stirling.*;import net.minecraft.client.Minecraft;import net.minecraft.client.gui.GuiGraphics;import net.minecraft.network.chat.Component;import net.minecraft.world.phys.BlockHitResult;import net.neoforged.api.distmarker.Dist;import net.neoforged.bus.api.SubscribeEvent;import net.neoforged.fml.common.EventBusSubscriber;import net.neoforged.neoforge.client.event.RenderGuiEvent;
/** Source no-GUI live look information represented with requested bars, real missinggear/overspeed warnings retained. */
@EventBusSubscriber(modid="hbm",value=Dist.CLIENT)
public final class StirlingOverlay {
 @SubscribeEvent public static void render(RenderGuiEvent.Post event){var mc=Minecraft.getInstance();if(mc.options.hideGui||mc.level==null||!(mc.hitResult instanceof BlockHitResult hit)||!(mc.level.getBlockState(hit.getBlockPos()).getBlock() instanceof StirlingBlock block))return;var pos=block.findCore(mc.level,hit.getBlockPos());if(pos==null||!(mc.level.getBlockEntity(pos) instanceof StirlingBlockEntity machine))return;var g=event.getGuiGraphics();var font=LegacyFonts.get();int x=g.guiWidth()/2+8,y=g.guiHeight()/2-10;{g.drawString(font,Component.translatable("block.hbm."+machine.kind.id),x,y,0xffff00,true);y+=12;double ratio=(double)machine.displayHeat/machine.kind.maxHeat();int color=ratio>1?0xff0000:((int)(255-255*ratio))<<16|((int)(255*ratio))<<8;bar(g,x,y,ratio,color);g.drawString(font,machine.displayHeat+"TU/t",x+2,y+1,0xffffff,true);y+=14;bar(g,x,y,machine.hasCog&&machine.getPowerExact().signum()>0?1:0,0x55ff55);g.drawString(font,(machine.hasCog?machine.getPowerExact().toString():"0")+"HE/t",x+2,y+1,0xffffff,true);y+=14;}if(machine.kind!=StirlingKind.CREATIVE){if(machine.displayHeat>machine.kind.maxHeat()){g.drawString(font,Component.translatable("gui.hbm.stirling.warning"),x,y,System.currentTimeMillis()%1000<500?0xff0000:0xffff00,true);y+=12;}if(!machine.hasCog)g.drawString(font,Component.translatable("gui.hbm.stirling.missing"),x,y,0xff0000,true);}}
 private static void bar(GuiGraphics g,int x,int y,double ratio,int color){g.fill(x+1,y+1,x+1+(int)(178*Math.max(0,Math.min(1,ratio))),y+11,0xa0000000|color&0xffffff);}
}
